async def test_buyorder_state_histories(client, db_session):
    listing, _ = await seed_listing(db_session)
    db_session.add(
        models.BuyorderStateHistory(
            listing_id=listing.id,
            old_user_keys=5,
            old_user_metal=0.0,
            old_top_competitor_keys=10,
            old_top_competitor_metal=0.0,
            old_is_outbid=True,
            old_lowest_seller_keys=2,
            old_lowest_seller_metal=0.0,
            new_user_keys=6,
            new_user_metal=0.0,
            new_top_competitor_keys=10,
            new_top_competitor_metal=0.0,
            new_is_outbid=True,
            new_lowest_seller_keys=2,
            new_lowest_seller_metal=0.0,
            outbid_changed=True,
        )
    )
    await db_session.commit()
    resp = await client.get("/api/buyorder_state_histories")
    assert resp.status_code == 200
    body = resp.json()
    assert len(body) == 1
    assert body[0]["outbid_changed"] is True
    assert body[0]["listing"]["item"]["name"] == "Key"


async def test_sellorder_states(client, db_session):
    l1, _ = await seed_listing(db_session, listing_id="L1", intent=Intent.sell)
    l2, _ = await seed_listing(db_session, listing_id="L2", intent=Intent.sell)
