async def test_refresh_buyorder_state_not_found(client):
    resp = await client.post("/api/buyorder_states/does-not-exist/refresh")
    assert resp.status_code == 404


async def test_refresh_buyorder_state_rejects_sell_listing(client, db_session):
    listing, _ = await seed_listing(db_session, intent=Intent.sell)
    resp = await client.post(f"/api/buyorder_states/{listing.id}/refresh")
    assert resp.status_code == 400
